/* ===== Помощник: ответы по руководству пользователя — без сети и без большой модели.
   Два ресурса: «руководство» (data/manual.json — разделы, нарезанные по заголовкам) и «индекс»
   (data/manual.bin — куски текста, их векторы в скрытых темах и матрица проекции признаков).
   Поиск гибридный: ключевые слова по куску + косинус в темах (скрытые темы собраны SVD по самому
   руководству, поэтому близкие по смыслу куски лежат рядом), плюс поправки — свой раздел приложения
   весомее, справочники разработчика ниже. Знак в знак с assistant/docs/индекс.py. ===== */
let РУК = null, РУКИ = null;
const РУК_D = 2048, РУК_БИТ = 65536;
async function рукДанные(){
  if(РУК && РУКИ) return {д: РУК, и: РУКИ};
  const t0 = Date.now();
  if(!РУК) РУК = JSON.parse(new TextDecoder().decode(await ресурс.взять('руководство')));
  if(!РУКИ) РУКИ = рукРазобрать(await ресурс.взять('индекс'), РУК);
  сообщить('Руководство загружено за ' + (Date.now() - t0) + ' мс: разделов ' + РУК.разделы.length + ', кусков ' + РУКИ.N);
