const РУК_БИТЫ1 = new Uint8Array(256);
for(let i = 0; i < 256; i++){ let c = 0, x = i; while(x){ c += x & 1; x >>= 1; } РУК_БИТЫ1[i] = c; }
/* первый этап: расстояние Хэмминга по битовым векторам — отбираем кандидатов */
function рукКандидаты(и, т, сколько){
  const знак = new Uint8Array(и.байтНаКусок);
  for(let j = 0; j < и.K; j++) if(т[j] > и.средн[j]) знак[j >> 3] |= 128 >> (j & 7);
  const пары = [];
